package com.lims.model;
public class Customer {private int customerId;private String customerName,phone,email,address,status;public int getCustomerId(){return customerId;}public void setCustomerId(int v){customerId=v;}public String getCustomerName(){return customerName;}public void setCustomerName(String v){customerName=v;}public String getPhone(){return phone;}public void setPhone(String v){phone=v;}public String getEmail(){return email;}public void setEmail(String v){email=v;}public String getAddress(){return address;}public void setAddress(String v){address=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}}
